struct Instance {
    pos_scale: vec4f,      // xyz = position, w = uniform scale
    color: vec4f,          // rgba (0.0 to 1.0)
    rotation: vec4f,       // quaternion (x, y, z, w)
    scale3d: vec4f,        // xyz = non-uniform scale (sx, sy, sz), w = custom/id
};

struct ComputeUniforms {
    time: f32,             // Scene time in seconds
    dt: f32,               // Frame delta time in seconds
    count: u32,            // Total active instances
    pad: u32,              // std140 16-byte alignment padding
};

// Rotates a 3D vector v by quaternion q
fn quatRotate(v: vec3f, q: vec4f) -> vec3f {
    return v + 2.0 * cross(q.xyz, cross(q.xyz, v) + q.w * v);
}

// Converts HSV color (h, s, v in [0, 1]) to RGB
fn hsv2rgb(c: vec3f) -> vec3f {
    let k = vec4f(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
    let p = abs(fract(c.xxx + k.xyz) * 6.0 - k.www);
    return c.z * mix(k.xxx, clamp(p - k.xxx, vec3f(0.0), vec3f(1.0)), c.y);
}

import { Scene, Arrange, Circle, Color } from "retiam";

export class CPULayoutScene extends Scene {
    public async run() {
        // CPU Mode: Ideal for 10-500 elements needing individual animation queues
        const grid = new Arrange(new Circle(0.4), 16)
            .forAll((i, circle) => {
                circle.paint.fill = Color.fromHSV(i / 16, 0.8, 1.0);
            })
            .arrangeGrid(4, 4, 0.3);

        this.add(grid);

        // Staggered reveal animation across items
        await this.play(grid.stagger(0.08).fadeIn());
    }
}

import { Scene, Arrange, Dot, Color, Vec3 } from "retiam";

export class GPUGridScene extends Scene {
    public async run() {
        const COUNT = 10000;
        const grid = new Arrange(new Dot(0.2), COUNT, { gpu: true })
            .arrangeGrid(100, 100, 0.1);

        this.add(grid);

        // CPU frame-by-frame updater: syncs changed transforms to GPU buffer
        grid.onUpdate((time, dt, arrange) => {
            const t = time * 0.003;
            arrange.forAll((i, dot) => {
                const row = Math.floor(i / 100);
                const col = i % 100;
                const wave = Math.sin((row + col) * 0.1 + t);
                dot.transform.scaling = new Vec3(1.0 + wave * 0.3, 1.0 + wave * 0.3, 1.0);
            });
        });
    }
}

import { Scene, Arrange, Circle, Color, CameraController } from "retiam";

export default class ArrangeComputeWaveScene extends Scene {
    public async run() {
        this.camera.position.set([0, -32, 36]);
        this.camera.lookAt([0, 0, 0]);
        this.clearColor(new Color(0.02, 0.02, 0.04, 1.0));
        new CameraController(this, this.camera);

        const COLS = 256;
        const ROWS = 256;
        const COUNT = COLS * ROWS; // 65,536 instances

        const grid = new Arrange(new Circle(0.12), COUNT, { gpu: true })
            .arrangeGrid(ROWS, COLS, 0.08);
        this.add(grid);

        // WebGPU Compute Shader: Runs directly on GPU VRAM with 0% CPU overhead
        grid.onCompute(`
            let i = id.x;
            if (i >= uniforms.count) { return; }

            let p = instances[i].pos_scale.xyz;
            let t = uniforms.time * 0.001; // Adjust time speed

            // 1. Multi-octave wave math
            let r = length(p.xy);
            let ripple = sin(r * 0.4 - t * 3.6);
            let crossWave = cos(p.x * 0.28 + t * 2.2) * sin(p.y * 0.28 - t * 1.8);
            let spiral = sin(r * 0.18 - atan2(p.y, p.x) * 2.0 - t * 1.4);

            // 2. 3D Elevation displacement
            let elevation = (ripple * 0.65 + crossWave * 0.45 + spiral * 0.3) * 3.2;
            instances[i].pos_scale.z = elevation;

            // 3. Scale pulsing on wave peaks
            let normElevation = elevation / 3.2;
            instances[i].pos_scale.w = clamp(0.7 + 0.6 * normElevation, 0.25, 1.75);

            // 4. Cyberpunk HSV color gradient via built-in hsv2rgb() helper
            let hue = fract((r * 0.025) + (normElevation * 0.22) + (t * 0.06));
            let rgb = hsv2rgb(vec3f(hue, 0.85, 1.0));
            instances[i].color = vec4f(rgb, 0.95);
        `);
    }
}

grid.onCompute(`
    fn getInterference(pos: vec2f, t: f32) -> f32 {
        let d1 = distance(pos, vec2f(10.0 * sin(t), 10.0 * cos(t)));
        let d2 = distance(pos, vec2f(-10.0 * sin(t), -10.0 * cos(t)));
        return sin(d1 * 0.5 - t * 3.0) + sin(d2 * 0.5 - t * 3.0);
    }

    @compute @workgroup_size(64, 1, 1)
    fn main(@builtin(global_invocation_id) global_id: vec3<u32>) {
        let i = global_id.x;
        if (i >= uniforms.count) { return; }

        let p = instances[i].pos_scale.xyz;
        let wave = getInterference(p.xy, uniforms.time * 0.001);

        instances[i].pos_scale.z = wave * 2.0;
        instances[i].color = vec4f(hsv2rgb(vec3f(wave * 0.25 + 0.5, 0.9, 1.0)), 1.0);
    }
`, { workgroupSize: [64, 1, 1] });
